def robust(a, v):
    c = ls(a, v)
    for i in range(40):
        r = np.linalg.norm(a @ c - v, axis=1)
        w = np.sqrt(np.minimum(1, 1.2 * np.median(r) / np.maximum(r, 1e-12)))
        c = ls(w[:, None] * a, w[:, None] * v)
    g = np.linalg.norm(a @ c - v, axis=1) < 4 * np.median(np.linalg.norm(a @ c - v, axis=1)) + 1e-10
    return (ls(a[g], v[g]), g)

def score(a, v):
    c = ls(a, v)
    h = np.sum(np.linalg.qr(a)[0] ** 2, axis=1)
    r = (a @ c - v) / (1 - h) if v.ndim == 1 else (a @ c - v) / (1 - h[:, None])
    return (np.mean(r * r) ** 0.5, c)

