def panel(p, key, kind):
    from scipy.optimize import minimize_scalar
    u = p['u']
    v = p[key]
    funcs = {'atan': np.arctan, 'tanh': np.tanh, 'rat': lambda u: u / np.sqrt(1 + u * u), 'abs': np.abs, 'softabs': lambda u: np.sqrt(1 + u * u), 'cos': np.cos}

    def design(u, k):
        h = funcs[kind](u * k) if kind not in ('abs',) else abs(u - k)
        return np.c_[aff(u), h]

    def opt(k, ret=False):
        a = design(u, k)
        Q = np.linalg.qr(a)[0]
        e = v - Q @ (Q.T @ v)
        err = np.mean((e / (1 - (Q * Q).sum(1))[:, None]) ** 2) ** 0.5
        return (err, ls(a, v)) if ret else err
    r = minimize_scalar(opt, bounds=(-0.35, 0.35) if kind == 'abs' else (0.35, 4), method='bounded')
